"""Tasks: generated by a model from the layer, then every key is checked without a model.

A task survives only if:
  * it cites claims of its own node, all with status "ok" (disputed facts never become answer keys);
  * its structure is valid for its type;
  * the correct answer is supported by the cited claims (word overlap / verbatim gap word / recomputed number);
  * agent A's course-text check passes (numbers come from the node's source units, no term before its node).
Rejected tasks are written to the report with the reason, never silently fixed.

Kept tasks are written in the organizers' format (docs/organizers/pack/01_схемы/task.schema.json; extra fields are
allowed by the pack, required ones are never dropped) and validated against that schema during the build.
"""
import ast
import json
import operator
import random
import re
from pathlib import Path

from kmg import checks as achecks
from kmg.config import ROOT, domain_pack
from kmg.structure import pack_prereq_terms

from . import llm

TYPES = ("single", "multiple", "order", "gap", "calc")  # names as in the organizers' task.schema.json
ALIASES = {"multi": "multiple"}  # older model outputs
KINDS = ("recall", "understanding", "transfer", "data")
SCHEMAS = ROOT / "docs" / "organizers" / "pack" / "01_схемы"
PROMPT = Path(__file__).resolve().parent / "prompts" / "tasks.md"
STOP = set("и в во на не но а с со к ко по о об от до из за для при что как это то же ли или у его ее её их "
           "так также только более менее чем который которая которые которых".split())


def _norm(s):
    return re.sub(r"\s+", " ", (s or "").lower().replace("ё", "е")).strip()


def _stems(s):
    return {w[:5] for w in re.findall(r"[a-zа-яё0-9]+", _norm(s)) if w not in STOP and len(w) > 2}


def _overlap(a, b):
    sa = _stems(a)
    if not sa:
        return 0.0
    return len(sa & _stems(b)) / len(sa)


# ---------- safe arithmetic for calc tasks ----------
_OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv,
        ast.Pow: operator.pow, ast.USub: operator.neg, ast.UAdd: operator.pos}
_FUNCS = {"ln": __import__("math").log, "log": __import__("math").log, "log10": __import__("math").log10,
          "sqrt": __import__("math").sqrt, "exp": __import__("math").exp, "pi": __import__("math").pi}


def safe_eval(expr, vars_):
    def ev(n):
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.Name):
            if n.id in vars_:
                return float(vars_[n.id])
            if n.id in _FUNCS and not callable(_FUNCS[n.id]):
                return _FUNCS[n.id]
            raise ValueError("unknown name %s" % n.id)
        if isinstance(n, ast.BinOp) and type(n.op) in _OPS:
            return _OPS[type(n.op)](ev(n.left), ev(n.right))
        if isinstance(n, ast.UnaryOp) and type(n.op) in _OPS:
            return _OPS[type(n.op)](ev(n.operand))
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and callable(_FUNCS.get(n.func.id)) and len(n.args) == 1:
            return _FUNCS[n.func.id](ev(n.args[0]))
        raise ValueError("unsupported expression")
    return ev(ast.parse(expr, mode="eval"))


# ---------- generation ----------
def _node_payload(n, later_terms):
    ok = [c for c in n["claims"] if c["status"] == "ok"]
    return {
        "node_id": n["id"], "title": n["title_novice"],
        "claims": [{"id": c["id"], "text": c["text"], "page": c["page"], "quote": c["quote"]} for c in ok],
        "terms": [{"term": t["term"], "definition": (t.get("definition") or {}).get("text")} for t in n.get("terms_defined", [])],
        "procedure": [p["text"] for p in n.get("procedure", [])],
        "numbers_conditions": [p["text"] for p in n.get("numbers_conditions", [])],
        "worked_examples": [{"label": w.get("label"), "condition": (w.get("condition") or {}).get("text"),
                             "steps": [s.get("text") for s in w.get("steps", [])],
                             "result": (w.get("result") or {}).get("text")} for w in n.get("worked_examples", [])],
        "formulas": [{"latex": f["latex"], "variables": f.get("variables", [])} for f in n.get("formulas", [])],
        "forbidden_terms": sorted(later_terms),
    }


BATCH = 10  # nodes per model call: keeps output well under max_tokens on big chapters


def _batches(nodes):
    """Group consecutive nodes by part, splitting big parts, so one call sees related steps together."""
    out, cur, cur_part = [], [], None
    for n in nodes:
        if cur and (n["part_id"] != cur_part and len(cur) >= BATCH // 2 or len(cur) >= BATCH):
            out.append(cur)
            cur = []
        cur.append(n)
        cur_part = n["part_id"]
    if cur:
        out.append(cur)
    return out


def generate(layer, log_path, min_total=15):
    nodes = sorted(layer["nodes"], key=lambda n: n["order"])
    defined_at = {}
    for n in nodes:
        for t in n.get("terms_defined", []):
            defined_at.setdefault(t["term"], n["order"])
    payload = []
    for n in nodes:
        later = {t for t, k in defined_at.items() if k > n["order"]}
        p = _node_payload(n, later)
        if p["claims"]:
            payload.append((n, p))
    batches = _batches([n for n, _ in payload])
    by_id = {n["id"]: p for n, p in payload}
    tasks, total = [], {"cost_usd": 0.0, "cost_usd_original": 0.0, "cached": True, "model": None, "calls": 0}
    def one(ib):
        i, b = ib
        want = max(3, -(-min_total * len(b) // len(payload)), len(b))
        system = [{"type": "text", "text": PROMPT.read_text(encoding="utf-8").replace("{min_total}", str(want))}]
        user = "Шаги курса (JSON):\n" + json.dumps([by_id[n["id"]] for n in b], ensure_ascii=False, indent=1)
        return llm.call("tasks", system, user, log_path=log_path, tag="tasks:%s:b%d" % (layer["chapter"]["id"], i + 1))
    # batches are independent: up to KMG_TASK_WORKERS model calls at once (results kept in batch order, same cache keys)
    from concurrent.futures import ThreadPoolExecutor
    import os
    with ThreadPoolExecutor(max_workers=max(1, int(os.environ.get("KMG_TASK_WORKERS", "4")))) as ex:
        results = list(ex.map(one, list(enumerate(batches))))
    for r in results:
        tasks += llm.parse_json(r["text"]).get("tasks", [])
        total["cost_usd"] += r["cost_usd"] or 0
        total["cost_usd_original"] += r["cost_usd_original"] or 0
        total["cached"] = total["cached"] and r["cached"]
        total["model"] = r["model"]
        total["calls"] += 1
    return tasks, total


# ---------- validation ----------
def _node_text(n):
    parts = [c["text"] for c in n["claims"] if c["status"] == "ok"] + [c["quote"] for c in n["claims"] if c["status"] == "ok"]
    for k in ("summary", "procedure", "numbers_conditions"):
        parts += [p["text"] for p in n.get(k, [])]
    parts += [(t.get("definition") or {}).get("text", "") + " " + t["term"] for t in n.get("terms_defined", [])]
    return "\n".join(parts)


def _correct_texts(t):
    ty = t["type"]
    if ty == "single":
        return [t["options"][t["answer"]]]
    if ty == "multiple":
        return [t["options"][i] for i in t["answer"]]
    if ty == "order":
        return list(t["items"])
    if ty == "gap":
        return [t["prompt"].replace("___", str(t["answer"]))]
    if ty == "calc":
        return [str(t["answer"])]
    return []


def validate(layer, raw_tasks, pack_terms):
    nodes = {n["id"]: n for n in layer["nodes"]}
    kept, rejected = [], []
    for i, t in enumerate(raw_tasks):
        why = None
        n = nodes.get(t.get("node_id"))
        ty = ALIASES.get(t.get("type"), t.get("type"))
        t = dict(t, type=ty)
        if not n:
            why = "нет такого узла"
        elif not isinstance(t.get("prompt"), str) or not t["prompt"].strip():
            why = "нет формулировки задания"
        elif not isinstance(t.get("explanation"), str) or not t["explanation"].strip():
            why = "нет пояснения к ответу"
        elif ty not in TYPES:
            why = "неизвестный тип %r" % ty
        else:
            claims = {c["id"]: c for c in n["claims"]}
            cids = t.get("claim_ids") or []
            if not cids or any(c not in claims for c in cids):
                why = "claim_ids пусты или не из этого узла"
            elif any(claims[c]["status"] != "ok" for c in cids):
                why = "ключ опирается на непроверенное утверждение"
        if not why:
            try:
                if ty in ("single", "multiple"):
                    opts = t["options"]
                    if not (3 <= len(opts) <= 5) or len(set(map(_norm, opts))) != len(opts):
                        why = "варианты: нужно 3–5 разных"
                    elif ty == "single" and not (isinstance(t["answer"], int) and 0 <= t["answer"] < len(opts)):
                        why = "answer вне диапазона"
                    elif ty == "multiple" and not (isinstance(t["answer"], list) and 2 <= len(set(t["answer"])) < len(opts)
                                                and all(isinstance(a, int) and 0 <= a < len(opts) for a in t["answer"])):
                        why = "multi: нужно ≥2 верных и не все"
                elif ty == "order":
                    if not (3 <= len(t.get("items", [])) <= 6):
                        why = "order: нужно 3–6 пунктов"
                elif ty == "gap":
                    if t.get("prompt", "").count("___") != 1 or not str(t.get("answer", "")).strip():
                        why = "gap: нужен ровно один ___ и ответ"
                elif ty == "calc":
                    c = t.get("calc") or {}
                    val = safe_eval(c["expr"], c.get("vars", {}))
                    tol = float(c.get("tolerance", 0.01))
                    ans = float(t["answer"])
                    if abs(val - ans) > max(tol, abs(val) * 0.005):
                        why = "calc: пересчёт %.4g ≠ ключ %.4g" % (val, ans)
            except (KeyError, TypeError, ValueError, ZeroDivisionError, SyntaxError) as e:
                why = "структура: %s" % e
        if not why:
            support = "\n".join(claims[c]["text"] + " " + claims[c]["quote"] for c in t["claim_ids"])
            ntext = _node_text(n)
            if ty == "gap":
                if _norm(str(t["answer"])) not in _norm(ntext):
                    why = "ответ пропуска не встречается в тексте шага"
            elif ty in ("single", "multiple"):
                formulas = " ".join(f["latex"] + " " + " ".join(v["symbol"] for v in f.get("variables", []))
                                    for f in n.get("formulas", []))
                for ct in _correct_texts(t):
                    # symbolic / numeric option ("β", "0,6%", "∂p/∂t"): word overlap is meaningless —
                    # require the option itself to appear in the cited claims, their quotes or the node's formulas
                    if len(_stems(ct)) < 2:
                        hay = _norm(support + " " + formulas).replace(" ", "")
                        if _norm(ct).replace(" ", "") not in hay:
                            why = "символьный ответ не найден в утверждениях/формулах: «%s»" % ct[:60]
                            break
                        continue
                    if _overlap(ct, support) < 0.5:
                        why = "верный вариант не подтверждается утверждениями: «%s»" % ct[:60]
                        break
            elif ty == "order":
                for it in t["items"]:
                    if _overlap(it, ntext) < 0.5:
                        why = "пункт порядка не из шага: «%s»" % it[:60]
                        break
        if not why:
            item = {"node_id": n["id"], "where": "task%d" % i,
                    "text": " ".join([t.get("prompt", "")] + _correct_texts(t) + [t.get("explanation", "")])}
            res = achecks.check_course_items(layer, [item], pack_terms)
            if not res["passed"]:
                why = "проверка A: " + "; ".join(x.get("msg", "") for x in res["issues"] if x["level"] == "error")[:200]
        if why:
            rejected.append({"index": i, "node_id": t.get("node_id"), "type": ty, "prompt": t.get("prompt"), "why": why})
            continue
        kept.append(official(t, n["id"], sum(1 for k in kept if k["node_id"] == n["id"]) + 1))
    return kept, rejected


def _letters(k):
    return [chr(ord("a") + i) for i in range(k)]


def official(t, node_id, num):
    """A checked task (model's internal shape: indices, '___') -> the organizers' task.schema.json shape.
    Extra fields (node_id, by, checked, accept, calc) are allowed by the pack."""
    ty = t["type"]
    tid = "%s.t%02d" % (node_id, num)
    out = {"id": tid, "type": ty, "step_id": node_id, "node_id": node_id, "claim_ids": list(t["claim_ids"]),
           "prompt": t["prompt"], "explanation": t.get("explanation", ""), "by": "model", "checked": "auto"}
    if t.get("kind") in KINDS:
        out["kind"] = t["kind"]
    if ty in ("single", "multiple"):
        ids = _letters(len(t["options"]))
        out["options"] = [{"id": ids[i], "text": o, "misconception": None} for i, o in enumerate(t["options"])]
        out["answer"] = ids[t["answer"]] if ty == "single" else [ids[i] for i in sorted(set(t["answer"]))]
    elif ty == "order":
        # options are stored in the order shown to the learner (shuffled, never already correct); answer = ids in
        # the correct order
        rnd = random.Random(tid)
        idx = list(range(len(t["items"])))
        while idx == sorted(idx):
            rnd.shuffle(idx)
        ids = _letters(len(idx))
        out["options"] = [{"id": ids[pos], "text": t["items"][i], "misconception": None} for pos, i in enumerate(idx)]
        out["answer"] = [ids[idx.index(i)] for i in range(len(idx))]
    elif ty == "gap":
        out["prompt"] = t["prompt"].replace("___", "{{1}}", 1)
        out["answer"] = [str(t["answer"])]
        out["accept"] = [[str(a) for a in t.get("accept", []) if str(a).strip()]]
    elif ty == "calc":
        c = t["calc"]
        out["answer"] = float(t["answer"])
        out["tolerance"] = float(c.get("tolerance", 0.01))
        out["unit"] = c.get("unit") or None
        out["calc"] = {"expr": c["expr"], "vars": c.get("vars", {})}
    return out


def upgrade(t):
    """A task of an older built course (kmg-tasks/0.1.0: indices, '___', items+shuffled) -> official shape.
    Used only by `build --assets-only`, so an old course keeps working with the new app until it is rebuilt."""
    if "step_id" in t:
        return t
    ty = ALIASES.get(t["type"], t["type"])
    num = int(t["id"].rsplit(".t", 1)[1]) if ".t" in t["id"] else 1
    base = {"type": ty, "claim_ids": t["claim_ids"], "prompt": t["prompt"], "explanation": t.get("explanation", "")}
    if ty in ("single", "multiple"):
        base.update(options=t["options"], answer=t["answer"])
    elif ty == "order":
        base.update(items=t["items"])
    elif ty == "gap":
        base.update(answer=t["answer"], accept=t.get("accept", []))
    elif ty == "calc":
        base.update(answer=t["answer"], calc=t["calc"])
    out = official(base, t["node_id"], num)
    if ty == "order" and t.get("shuffled"):  # keep the order the learner saw before
        ids = _letters(len(t["items"]))
        out["options"] = [{"id": ids[pos], "text": t["items"][i], "misconception": None} for pos, i in enumerate(t["shuffled"])]
        out["answer"] = [ids[t["shuffled"].index(i)] for i in range(len(t["items"]))]
    return out


def schema_errors(doc, schema_file):
    """Validate a document against an organizers' schema; returns readable messages (empty = valid)."""
    import jsonschema
    path = SCHEMAS / schema_file
    if not path.exists():
        return ["нет схемы организаторов %s" % path]
    schema = json.loads(path.read_text(encoding="utf-8"))
    v = jsonschema.Draft202012Validator(schema)
    out = []
    for e in sorted(v.iter_errors(doc), key=lambda e: list(e.absolute_path)):
        where = "/".join(str(x) for x in e.absolute_path) or "(корень)"
        item = doc
        try:
            for x in list(e.absolute_path)[:2]:
                item = item[x]
            ident = item.get("id") if isinstance(item, dict) else None
        except (KeyError, IndexError, TypeError):
            ident = None
        out.append("%s: %s%s" % (where, e.message[:200], " (id %s)" % ident if ident else ""))
    return out


def internal(t):
    """Organizers' shape (tasks.json of an earlier build) -> the shape `validate` checks; inverse of `official`."""
    ty = t["type"]
    out = {"node_id": t.get("node_id") or t["step_id"], "claim_ids": t["claim_ids"], "type": ty, "prompt": t["prompt"],
           "explanation": t.get("explanation", ""), "kind": t.get("kind")}
    if ty in ("single", "multiple"):
        ids = [o["id"] for o in t["options"]]
        out["options"] = [o["text"] for o in t["options"]]
        out["answer"] = ids.index(t["answer"]) if ty == "single" else [ids.index(a) for a in t["answer"]]
    elif ty == "order":
        txt = {o["id"]: o["text"] for o in t["options"]}
        out["items"] = [txt[a] for a in t["answer"]]
    elif ty == "gap":
        out["prompt"] = t["prompt"].replace("{{1}}", "___", 1)
        out["answer"] = t["answer"][0]
        out["accept"] = (t.get("accept") or [[]])[0]
    elif ty == "calc":
        c = dict(t.get("calc") or {})
        c.update(unit=t.get("unit"), tolerance=t.get("tolerance") or 0.01)
        out["answer"], out["calc"] = t["answer"], c
    return out


def build_tasks(layer, out_dir, log_path, min_total=15, reuse=False, drop_nodes=()):
    """reuse=True: no model call — the tasks of the previous build (out_dir/tasks.json) are re-checked against the
    current layer (e.g. after a fact edit): tasks whose keys no longer hold go to the report as rejected."""
    pack_terms = pack_prereq_terms(domain_pack(layer["chapter"]["domain_pack"]))
    prev = Path(out_dir) / "tasks.json"
    if reuse and prev.exists():
        raw = []
        for t in json.loads(prev.read_text(encoding="utf-8")).get("tasks", []):
            if (t.get("node_id") or t.get("step_id")) in drop_nodes:   # facts of this node changed: its old tasks are dropped
                continue
            try:
                raw.append(internal(t))
            except (KeyError, ValueError, TypeError, IndexError):
                pass
        r = {"cost_usd": 0.0, "cost_usd_original": 0.0, "cached": True, "model": "reuse:" + prev.name, "calls": 0}
    else:
        raw, r = generate(layer, log_path, min_total=min_total)
    kept, rejected = validate(layer, raw, pack_terms)
    types = sorted({t["type"] for t in kept})
    doc = {"chapter": layer["chapter"]["id"], "schema": "glava-kurs/task.schema.json", "tasks": kept}
    errors = schema_errors(doc, "task.schema.json")
    report = {"schema": "kmg-tasks/0.2.0", "chapter": layer["chapter"]["id"], "generated": len(raw),
              "kept": len(kept), "rejected": rejected, "types": types,
              "kinds": sorted({t["kind"] for t in kept if t.get("kind")}),
              "meets_tz": len(kept) >= min_total and len(types) >= 4,
              "schema_errors": errors, "schema_ok": not errors,
              "cost_usd": round(r["cost_usd"], 6), "cost_usd_original": round(r["cost_usd_original"], 6),
              "cached": r["cached"], "model": r["model"], "calls": r["calls"]}
    Path(out_dir).mkdir(parents=True, exist_ok=True)
    (Path(out_dir) / "tasks.json").write_text(json.dumps(doc, ensure_ascii=False, indent=1), encoding="utf-8")
    return kept, report
